function SettingsForm() {
  const [profile, setProfile] = useState(initial);

  function NicknameField() {           // defined INSIDE SettingsForm
    const [draft, setDraft] = useState(profile.nickname);
    return <input value={draft} onChange={(e) => setDraft(e.target.value)} />;
  }

  return <form>...<NicknameField />...</form>;
}

Each SettingsForm render creates a new NicknameField function object, so the element's ___b1___ is a different reference every render. React treats that as a change and ___b2___ the subtree, wiping its state. The fix: move the definition to ___b3___ and pass data via props.

