function SettingsForm() {
  const [profile, setProfile] = useState(initial);

  function NicknameField() {           // defined INSIDE SettingsForm
    const [draft, setDraft] = useState(profile.nickname);
    return <input value={draft} onChange={(e) => setDraft(e.target.value)} />;
  }

  return <form>...<NicknameField />...</form>;
}

Каждый рендер SettingsForm создаёт новый объект функции NicknameField, поэтому ___b1___ элемента — каждый рендер другая ссылка. React считает это изменением и ___b2___ поддерево, стирая его состояние. Лечение: вынести определение на ___b3___ и передавать данные через пропсы.
